/* @autogenerated */
import { BulkEditField } from 'app/shared/toolkit/bulk-edit/bulk-edit.model';
import { TemplateVariable } from 'app/features/template/template-variable/model/template-variable.model';
import { BaseBulkEditAction } from 'app/shared/toolkit/action/base-bulk-edit-action';
import { BulkEditDialogData } from 'app/shared/toolkit/bulk-edit/bulk-edit-dialog.component';
import { Component, inject } from '@angular/core';
import { TemplateVariableRepository } from 'app/features/template/template-variable/repository/template-variable-repository.service';

/** Edición masiva de template variable: los campos que se pueden cambiar en bloque. */
@Component({ selector: 'template-variable-view-bulk-edit-action', standalone: false, template: '' })
export class TemplateVariableViewBulkEditActionComponent extends BaseBulkEditAction<TemplateVariable> {
  readonly name = 'bulkEdit';
  protected readonly scope = 'template/template-variable';
  protected readonly repository = inject(TemplateVariableRepository);

  protected override keyOf(item: TemplateVariable): string {
    return String(item.uid);
  }

  /** Los campos que se pueden editar en bloque y el tipo de cada uno. */
  protected bulkFields(): readonly BulkEditField<TemplateVariable>[] {
    return [
      { name: 'code', label: this.text('fieldCode'), type: 'text' },
      { name: 'type', label: this.text('fieldType'), type: 'text' },
      { name: 'value', label: this.text('fieldValue'), type: 'text', optional: true },
    ];
  }

  protected override toDialogData(count: number): BulkEditDialogData<TemplateVariable> {
    return {
      title: this.text('dialogTitle'),
      count,
      singular: this.text('selectedSingular'),
      plural: this.text('selectedPlural'),
      confirm: this.text('confirm'),
      cancel: this.text('cancel'),
      fields: this.bulkFields(),
    };
  }
}
